commonjs='''
const $=id=>document.getElementById(id);const icons=ICONJSON;
function ico(name){return icons[name]||icons['circle-help']}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let theme='light';try{theme=localStorage.getItem('relai-terminal-concept-theme')||'light'}catch{}function setTheme(value){document.documentElement.dataset.theme=value;$('theme').innerHTML=ico(value==='dark'?'sun':'moon');$('theme').setAttribute('aria-label',value==='dark'?'Switch to light mode':'Switch to dark mode');try{localStorage.setItem('relai-terminal-concept-theme',value)}catch{}}setTheme(theme);$('theme').onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4000)}
function modal(title,body,action=null){$('dialog-title').textContent=title;$('dialog-body').innerHTML=body;$('dialog-confirm').hidden=!action;$('dialog-confirm').textContent=action?.label||'Continue';$('dialog-confirm').onclick=()=>{$('dialog').close();action?.run()};$('dialog').showModal()}$('dialog-close').onclick=()=> $('dialog').close();
const agentData={codex:{name:'Codex',letter:'C',route:'Native app-server',config:'Native config resolved by Codex',skillSource:'Native skill catalog',model:'Agent default',path:'/home/you/projects/relai',native:'cx-7a21',linked:true,state:'Ready',origin:'Managed by Relai'},claude:{name:'Claude Code',letter:'C',route:'Native Agent SDK',config:'User + project + local settings',skillSource:'Native discovery via the SDK',model:'Agent default',path:'/home/you/projects/relai',native:'cl-9b42',linked:false,state:'Unknown',origin:'Saved session'},opencode:{name:'OpenCode',letter:'O',route:'Native server · ACP also available',config:'Merged native configuration',skillSource:'.opencode / .claude / .agents skills',model:'Agent default',path:'/home/you/projects/website',native:'oc-8f31',linked:true,state:'Needs approval',origin:'Connected native server'}};
function agentBadge(id){return `<span class="agent ${id}"><i class="agent-dot"></i>${agentData[id].name}</span>`}
function agentButtons(){document.querySelectorAll('[data-agent]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.agent===activeAgent);b.classList.toggle('active',b.dataset.agent===activeAgent);const small=b.querySelector('small'),a=agentData[b.dataset.agent];if(small)small.textContent=a.name+' · '+(a.linked?'connected':'saved');b.onclick=()=>{activeAgent=b.dataset.agent;render()}})}
'''.replace('ICONJSON',json.dumps(icons))
def shell(title,body,js,nav=True):
 bar='<header class="appbar"><a class="brand" href="index.html" style="color:var(--text);text-decoration:none"><span class="logo">r</span>relai</a><span class="breadcrumb">'+title+'</span><span class="grow"></span><span class="demo">Design exploration · simulated data</span><a class="btn" href="index.html">All concepts</a><button class="iconbtn" id="theme" aria-label="Switch theme"></button></header>'
 dialogs='<dialog id="dialog" aria-labelledby="dialog-title"><h2 id="dialog-title"></h2><div id="dialog-body"></div><footer class="modal-footer"><button class="btn" id="dialog-close">Close</button><button class="btn primary" id="dialog-confirm" hidden>Continue</button></footer></dialog><div class="toast" id="toast" role="status" hidden></div>'
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relai — '+title+'</title><style>@font-face{font-family:Plex;src:url(data:font/ttf;base64,'+font+')}'+css+'</style></head><body>'+bar+body+dialogs+'<script>'+commonjs+js+'</script></body></html>'
 html=html.replace('<head>','<head><!-- Embedded IBM Plex font and Lucide icons; licenses follow. -->')
 html=html.replace('</body>', '<script type="application/json" id="asset-licenses">'+json.dumps({'IBM Plex':(root/'fonts/IBM-Plex-OFL.txt').read_text(),'Lucide':(root/'icons/LICENSE').read_text()})+'</script></body>')
 html=re.sub(r'\[icon:([\w-]+)\]',lambda m:icons.get(m[1],icons['circle-help']),html)
 return html
sidebar='''<aside class="sidebar"><button class="btn primary compose" id="compose-example">[icon:pencil]Compose relai</button><a class="nav-item" href="01-session-workspace.html">[icon:inbox]Inbox<span class="count">4</span></a><a class="nav-item" href="03-session-connections.html">[icon:messages-square]Sessions<span class="count">3</span></a><a class="nav-item" href="02-agent-profiles.html">[icon:settings]Agents & settings</a><div class="section-label">Your sessions</div><button class="nav-item session-card" data-agent="codex"><span class="agent-icon codex">C</span><span>Relai interface<small>Codex · local session</small></span></button><button class="nav-item session-card" data-agent="claude"><span class="agent-icon claude">C</span><span>Workspace architecture<small>Claude Code · saved</small></span></button><button class="nav-item session-card" data-agent="opencode"><span class="agent-icon opencode">O</span><span>Website direction<small>OpenCode · connected</small></span></button><div class="section-label">Projects</div><div class="nav-item">[icon:folder]relai</div><div class="nav-item">[icon:folder]website</div><p class="small muted" style="padding:10px;margin-top:25px">Your agent keeps its own configuration. Relai handles the connection.</p></aside>'''
workspace='''<div class="layout">SIDEBAR<div class="workspace"><main class="reading"><header class="reading-header"><div class="chips" style="margin-bottom:15px"><span class="muted small">Inbox / Relai</span><span class="grow"></span><button class="btn" id="session-button">[icon:messages-square]Session</button></div><h1>Refine the workspace navigation</h1><div class="chips"><span id="conversation-agent"></span><span class="chip">[icon:folder]<span id="conversation-repo">relai</span></span><span class="chip" id="conversation-state"></span></div></header><div class="message-stream"><article class="message"><div class="meta"><span class="agent-icon">Y</span><strong>You</strong><span class="muted">Prompt</span><time>14:32</time></div><p>Keep the interface compact and make it easier to understand which session is receiving my prompt.</p></article><article class="message agent-message" id="agent-message"><div class="meta"><span id="message-agent"></span><span class="muted">Response</span><time>14:42</time></div><p>I suggest keeping the conversation in focus and placing session details in a small panel you can open when needed.</p><p><strong>Your prompts stay in Relai.</strong> The agent’s native configuration and tools stay with the agent.</p><div class="notice"><strong>Session context</strong>The native session can contain several Relais with different titles.</div></article><div id="conversation-banner"></div></div><footer class="reading-bottom"><button class="btn" id="reply">[icon:reply]Reply</button><span id="reply-agent"></span><span class="grow"></span><span class="muted small" id="delivery-hint"></span><div class="replybox" id="replybox" hidden><textarea id="prompt" aria-label="Reply prompt" placeholder="What should we work on next?"></textarea><footer><span class="muted small">Markdown supported · preview only</span><button class="btn primary" id="send-prompt">Send prompt [icon:arrow-up-right]</button></footer></div></footer></main><aside class="session-drawer" id="drawer" aria-label="Session details"><header class="drawer-header"><div class="drawer-title"><span id="drawer-avatar"></span><div><strong id="drawer-name"></strong><div class="small muted" id="drawer-origin" style="margin-top:5px"></div></div><span class="grow"></span><button class="iconbtn" id="close-drawer" aria-label="Close session panel">[icon:x]</button></div></header><nav class="tabs" aria-label="Session panel"><button class="tab" data-tab="overview" aria-pressed="true">Overview</button><button class="tab" data-tab="activity" aria-pressed="false">Activity</button><button class="tab" data-tab="terminal" aria-pressed="false">Terminal</button></nav><div class="drawer-body" id="drawer-body"></div></aside></div></div>'''.replace('SIDEBAR',sidebar)
workspacejs='''
let activeAgent='codex',activeTab='overview';
function render(){agentButtons();const a=agentData[activeAgent];$('conversation-agent').innerHTML=$('message-agent').innerHTML=$('reply-agent').innerHTML=agentBadge(activeAgent);$('drawer-name').textContent=a.name;$('drawer-origin').textContent=a.origin;$('drawer-avatar').innerHTML=`<span class="agent-icon ${activeAgent}">${a.letter}</span>`;$('conversation-state').textContent=a.linked?a.state:'Needs connection';$('conversation-repo').textContent=activeAgent==='opencode'?'website':'relai';$('delivery-hint').textContent=a.linked?'Same native session':'Resume this saved session before replying';$('send-prompt').disabled=!a.linked;$('conversation-banner').innerHTML=!a.linked?'<div class="notice attention"><strong>History is available. Live activity is unconfirmed.</strong>Resume this session in Relai to receive new responses. This does not attach to a terminal already running elsewhere.</div>':'';$('agent-message').style.background=`linear-gradient(110deg,var(--${{codex:'blue',claude:'orange',opencode:'grey'}[activeAgent]}bg),var(--panel) 65%)`;document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.tab===activeTab);b.onclick=()=>{activeTab=b.dataset.tab;render()}});
if(activeTab==='overview'){$('drawer-body').innerHTML=`<dl class="details-list"><div><dt>Native session</dt><dd>${activeAgent==='codex'?'Relai interface':activeAgent==='claude'?'Workspace architecture':'Website direction'}<br><span class="muted small">${a.native}</span></dd></div><div><dt>Local folder</dt><dd>${a.path}</dd></div><div><dt>Connection</dt><dd>${a.linked?'<span class="status-dot"></span>Connected':'Saved history · not connected'}<br><span class="muted small">${a.origin}</span></dd></div><div><dt>Configuration</dt><dd>Inherited from ${a.name}<br><span class="muted small">Personal settings + project settings</span></dd></div></dl>${!a.linked?'<button class="btn primary" id="resume">Resume in Relai</button>':'<div class="notice"><strong>One session, one active owner</strong>New prompts use this connection. Closing the panel keeps the session available.</div>'}${activeAgent==='opencode'&&a.state==='Needs approval'?'<div class="notice attention"><strong>Permission requested</strong>The agent wants to run a project command.<div class="approval-actions"><button class="btn primary" id="allow">Allow once</button><button class="btn" id="deny">Deny</button></div></div>':''}<a class="btn" href="02-agent-profiles.html" style="margin-top:15px">${ico('settings')}Agent settings</a>`;if($('resume'))$('resume').onclick=()=>modal('Resume this saved session?','<p>Relai will resume the same native session with the agent’s settings.</p><div class="notice">If this session is active in another terminal, check it there first. A saved history does not prove that it is stopped.</div>',{label:'Preview resume',run:()=>{a.linked=true;a.origin='Managed by Relai';a.state='Ready';render();toast('Preview only · no agent was started')}});for(const action of ['allow','deny'])if($(action))$(action).onclick=()=>{a.state='Ready';render();toast('Preview only · permission '+(action==='allow'?'allowed once':'denied'))}}
if(activeTab==='activity')$('drawer-body').innerHTML=`<h3>Session activity</h3><p class="muted small">${a.linked?'Events received from the connected runtime.':'Saved events only. New activity requires a connection.'}</p><div class="event"><time>14:32</time><div>Prompt accepted<p>Relai → native session ${a.native}</p></div></div><div class="event"><time>14:33</time><div>Inspecting project files<p>Native tool activity</p></div></div><div class="event"><time>14:42</time><div>Response received<p>Conversation updated</p></div></div><div class="notice">Activity events are separate from terminal output. A quiet terminal does not mean the agent has finished.</div>`;
if(activeTab==='terminal')$('drawer-body').innerHTML=`<div class="chips"><span class="chip">${activeAgent==='opencode'?'Native terminal preview':'Command output'}</span><span class="chip">Read only</span></div><p class="muted small">${activeAgent==='opencode'?'A native OpenCode terminal can share the same exposed server.':'Output captured from this session. This is not a mirror of an unrelated terminal.'}</p><div class="terminal"><div class="terminal-top"><i></i><i></i><i></i><span style="margin-left:6px">${a.name} · example output</span></div><pre><span class="green">$ git diff --stat</span>\n src/Sidebar.tsx  | 24 +++++++++\n src/workspace.css | 38 +++++++++++++\n\n 2 files changed\n\n<span class="green">$ npm run check</span>\n Checks passed.\n\n Waiting for the next prompt.</pre></div><div class="notice"><strong>Closing this view does not stop the agent.</strong>${a.linked?'Relai keeps its session connection.':'This is saved example output. No live terminal is connected.'}</div>${activeAgent==='opencode'?'<button class="btn" id="native-terminal">Open native terminal</button>':'<button class="btn" id="native-terminal">Native terminal options</button>'}`;
if($('native-terminal'))$('native-terminal').onclick=()=>modal('Native terminal connection',activeAgent==='opencode'?'<p>For OpenCode, a TUI can attach to a reachable server. The agent and the UI continue to use the same server.</p><div class="notice">This prototype shows the UX only. No terminal is opened.</div>':'<p>This structured connection does not guarantee attachment to an agent terminal started elsewhere.</p><p>Relai can own a dedicated terminal in a terminal-only integration mode, or provide native resume after a controlled handoff. It must avoid starting a second process on the same active session.</p>');}
$('close-drawer').onclick=()=>$('drawer').hidden=true;$('session-button').onclick=()=>$('drawer').hidden=!$('drawer').hidden;$('reply').onclick=()=>{$('replybox').hidden=!$('replybox').hidden;if(!$('replybox').hidden)$('prompt').focus()};$('send-prompt').onclick=()=>{if(!$('prompt').value.trim())return $('prompt').focus();toast(agentData[activeAgent].state==='Needs approval'?'Preview only · prompt would wait until the approval is resolved':'Preview only · prompt would use the same native session')};$('compose-example').onclick=()=>modal('Compose relai','<p>Keep the existing composer: choose an existing native session, or an agent and local folder for a new session.</p><p>Connection details are handled behind the scenes, with a clear recovery action when needed.</p>');render();
'''
(out/'01-session-workspace.html').write_text(shell('Session workspace',workspace,workspacejs))
profiles='''<div class="layout">SIDEBAR<main class="content"><header class="page-intro"><span class="muted small">Settings / Agents</span><h1 style="margin-top:9px">Keep each agent’s own setup.</h1><p>Use your native settings by default. Relai only adds the connection and the small overrides you choose.</p></header><div class="card"><div class="card-top"><span id="profile-avatar"></span><div><h2 id="profile-name"></h2><span id="profile-route" class="muted small"></span></div><span class="grow"></span><span class="chip success">Example connection</span></div></div><nav class="tabs" style="padding-left:0;margin-bottom:18px" aria-label="Agent settings"><button class="tab" data-profile-tab="config" aria-pressed="true">Configuration</button><button class="tab" data-profile-tab="skills" aria-pressed="false">Skills</button><button class="tab" data-profile-tab="compatibility" aria-pressed="false">Compatibility</button></nav><div id="profile-body"></div><p class="about">These are proposed controls. They do not read your computer or change an agent’s configuration.</p></main></div>'''.replace('SIDEBAR',sidebar)
profilesjs='''
let activeAgent='codex',profileTab='config';const profilePrefs={codex:{inherit:true,model:'default',approval:'native'},claude:{inherit:true,model:'default',approval:'native'},opencode:{inherit:true,model:'default',approval:'native'}};const skillSelection={codex:new Set(['code-review','api-design']),claude:new Set(['code-review','api-design']),opencode:new Set(['code-review','api-design'])};let compat='supported';
function nativePath(){return activeAgent==='codex'?'~/.codex/config.toml':activeAgent==='claude'?'~/.claude/settings.json':'~/.config/opencode/opencode.json'}
function render(){agentButtons();const a=agentData[activeAgent],pref=profilePrefs[activeAgent];$('profile-name').textContent=a.name;$('profile-route').textContent=a.route;$('profile-avatar').innerHTML=`<span class="agent-icon ${activeAgent}">${a.letter}</span>`;document.querySelectorAll('[data-profile-tab]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.profileTab===profileTab);b.onclick=()=>{profileTab=b.dataset.profileTab;render()}});
if(profileTab==='config'){$('profile-body').innerHTML=`<section class="card"><div class="form-row"><div><label>Inherit native configuration</label><p>Keep ${a.name}’s personal settings, project rules and skills.</p></div><button class="switch" id="inherit" role="switch" aria-label="Inherit native configuration" aria-checked="${pref.inherit}"></button></div><div class="scope-label">Configuration sources</div><div class="layer">${ico('settings')}<span>Personal settings<small class="config-path">${nativePath()}</small></span><span class="chip">Native</span></div><div class="layer">${ico('folder')}<span>Project settings and instructions<small class="config-path">${a.path} · resolved by the agent</small></span><span class="chip">Native</span></div><div class="layer">${ico('sliders-horizontal')}<span>Relai overrides<small>${pref.inherit?'None · use native defaults':'Only the choices below · new sessions'}</small></span><span class="chip">Optional</span></div><div class="notice"><strong>The agent resolves the configuration.</strong>Relai does not merge every agent’s settings with one generic rule. Existing sessions may keep the configuration they started with.</div><button class="btn" id="show-native">${ico('file-text')}View native settings example</button></section><section class="card" id="overrides" ${pref.inherit?'hidden':''}><h2>Overrides for new sessions</h2><p>These choices apply to future sessions launched from Relai. Existing sessions keep their current settings.</p><div class="form-row"><label for="model">Model</label><select class="field" id="model"><option value="default">Agent default</option><option value="example-model">Example model from native catalog</option></select></div><div class="form-row"><label for="approval">Permissions</label><select class="field" id="approval"><option value="native">Native permission policy</option><option value="ask">Ask before supported tool actions</option></select></div><div class="notice">A Relai override cannot override mandatory policies enforced by the agent.</div><button class="btn primary" id="save-profile">Save preview</button></section>`;$('inherit').onclick=()=>{pref.inherit=!pref.inherit;render();$('inherit').focus()};if($('model')){$('model').value=pref.model;$('approval').value=pref.approval;$('model').onchange=e=>pref.model=e.target.value;$('approval').onchange=e=>pref.approval=e.target.value;$('save-profile').onclick=()=>toast('Preview saved in memory · native settings unchanged')}$('show-native').onclick=()=>modal('Native settings example',`<p class="config-path">${nativePath()}</p><div class="native-file">${esc(activeAgent==='codex'?'# Example native Codex configuration\\n# Relai asks Codex for the resolved configuration.':activeAgent==='claude'?'{ "permissions": { "defaultMode": "default" } }':'{ "permission": { "edit": "ask" } }')}</div><p class="muted small">Illustrative content. A real integration opens the actual source file after the user requests it.</p>`)}
if(profileTab==='skills'){const editable=activeAgent==='claude';$('profile-body').innerHTML=`<section class="card"><h2>Skills available to ${a.name}</h2><p>Keep the agent’s native discovery. A shared SKILL.md does not guarantee identical behavior in every agent.</p><div class="notice"><strong>${editable?'Native selection capability · example':'Inherited skill catalog'}</strong>${editable?'This connector can expose the native SDK skill selection when the installed version supports it. Changes here apply to new sessions.':'This preview exposes discovery only. Use the agent’s native configuration to change availability.'}</div>${[['code-review','Review implementation changes','Project'],['api-design','Plan API boundaries and contracts','Personal'],['release-notes','Draft a release summary','Project']].map(([name,description,scope])=>`<div class="skill"><span class="chip">${ico('notebook')}</span><div class="copy"><strong>${name}</strong><p>${description}</p><span class="muted small">${scope} · ${editable?'Available in new sessions':'Discovered · inherited'}</span></div>${editable?`<button class="switch" data-skill="${name}" role="switch" aria-label="Enable ${name} in new sessions" aria-checked="${skillSelection[activeAgent].has(name)}"></button>`:'<span class="chip">Native</span>'}</div>`).join('')}<p class="small muted">Listing a skill does not prove it has been loaded or used during the current turn.</p><button class="btn" id="skill-detail">View skill details</button></section>`;document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{const set=skillSelection[activeAgent],name=b.dataset.skill;set.has(name)?set.delete(name):set.add(name);b.setAttribute('aria-checked',set.has(name));toast('Preview only · skill preference for new sessions')});$('skill-detail').onclick=()=>modal('Skill provenance','<dl class="details-list"><div><dt>Name</dt><dd>code-review</dd></div><div><dt>Scope</dt><dd>Project</dd></div><div><dt>Discovery</dt><dd>Reported by the agent connector</dd></div><div><dt>Usage in this session</dt><dd>Not confirmed</dd></div></dl><div class="notice">Project trust, settings, native permissions and the installed agent version determine whether a skill can be used.</div>')}
if(profileTab==='compatibility'){const messages={supported:['Supported connection','Required operations are available. Optional features are shown only when confirmed.'],new:['Agent update detected','Recheck the native interface. A new version does not automatically require a Relai update.'],limited:['Limited connection','History remains available. Prompt delivery is unavailable until the connector supports this protocol.'],missing:['Agent unavailable','Keep the saved sessions visible. Locate the executable or install the agent to resume work.']};const [heading,copy]=messages[compat];$('profile-body').innerHTML=`<section class="card"><div class="scenario-bar"><label for="compat-scenario">Preview state</label><select class="field" id="compat-scenario"><option value="supported">Supported connection</option><option value="new">Agent updated</option><option value="limited">Unsupported interface</option><option value="missing">Executable missing</option></select></div><div class="notice ${compat==='limited'||compat==='missing'?'attention':''}"><strong>${heading}</strong>${copy}</div><dl class="details-list"><div><dt>Native interface</dt><dd>${a.route}</dd></div><div><dt>Installed version</dt><dd>Example detected version · not your computer</dd></div><div><dt>Connection checks</dt><dd>Native initialization + supported operations + session control</dd></div></dl><ul class="checklist"><li>${ico('check')}Saved history remains separate from live control</li><li>${ico(compat==='limited'||compat==='missing'?'x':'check')}Prompt delivery ${compat==='limited'||compat==='missing'?'unavailable':'available'}</li><li>${ico('check')}Other agent connectors stay independent</li></ul><div class="actions"><button class="btn" id="recheck">${ico('refresh-cw')}Recheck connection</button><button class="btn" id="connection-details">Connection details</button></div></section>`;$('compat-scenario').value=compat;$('compat-scenario').onchange=e=>{compat=e.target.value;render();$('compat-scenario').focus()};$('recheck').onclick=()=>{compat='supported';render();toast('Simulated check passed · no executable was inspected')};$('connection-details').onclick=()=>modal('Connection details',`<div class="native-file">Agent: ${a.name}\nInterface: ${a.route}\nScope: local example environment\nControl: ${compat==='limited'?'unavailable':'example capability'}\nEvidence: simulated connection check</div><p>Relai checks the interface it actually uses. The agent’s version string alone is not enough to prove compatibility.</p>`)}}
$('compose-example').onclick=()=>modal('Configuration in Compose relai','<p>Keep the normal composer simple: agent, folder, title and prompt.</p><p>The session inherits this agent profile. Advanced overrides stay in settings, away from every prompt.</p>');render();
'''
(out/'02-agent-profiles.html').write_text(shell('Agent profiles',profiles,profilesjs))
connections='''<div class="layout">SIDEBAR<main class="content"><header class="page-intro"><span class="muted small">Workspace / Sessions</span><h1 style="margin-top:9px">Find the session. Know what you can do.</h1><p>Saved history is not a live connection. Give each session a clear status and one useful next action.</p></header><section class="card table-card"><table class="table"><thead><tr><th>Native session</th><th>Agent</th><th>Local folder</th><th>Connection</th><th>Next action</th></tr></thead><tbody id="sessions-table"></tbody></table></section><section class="card" id="connection-detail"><h2 id="connection-heading">Choose a session</h2><p id="connection-copy" class="muted">Inspect its connection before replying.</p><div id="connection-content"></div></section><section class="card"><h2>When an agent is updated</h2><p>The connector rechecks the native interface and only enables operations it can confirm.</p><div class="steps"><div class="step">Version changed<small>Keep your history</small></div>[icon:chevron-right]<div class="step">Check connection<small>Protocol + useful operations</small></div>[icon:chevron-right]<div class="step">Ready or limited<small>One clear next action</small></div></div><button class="btn" id="preview-update">Preview a compatibility issue</button></section><p class="about">All connections and recovery actions are simulated. Relai does not inspect or control processes on your computer from these HTML files.</p></main></div>'''.replace('SIDEBAR',sidebar)
connectionsjs='''
let activeAgent='codex',selectedSession=0;const examples=[{id:'cx-7a21',title:'Relai interface',agent:'codex',path:'/home/you/projects/relai',connection:'Connected',action:'Open session',kind:'managed'},{id:'cl-9b42',title:'Workspace architecture',agent:'claude',path:'/home/you/projects/relai',connection:'Saved history',action:'Resume in Relai',kind:'saved'},{id:'oc-8f31',title:'Website direction',agent:'opencode',path:'/home/you/projects/website',connection:'Needs connection',action:'Connect server',kind:'server'},{id:'cx-external',title:'Relai interface',agent:'codex',path:'/home/you/projects/relai',connection:'Activity unknown',action:'Check connection',kind:'external'}];
function render(){agentButtons();for(const id of ['codex','claude','opencode']){const row=examples.find(s=>s.agent===id),label=document.querySelector(`[data-agent="${id}"] small`);if(label)label.textContent=agentData[id].name+' · '+row.connection.toLowerCase()}$('sessions-table').innerHTML=examples.map((s,index)=>`<tr><td><strong style="font-weight:500">${s.title}</strong><small class="muted" style="display:block;margin-top:4px">${s.id}</small></td><td>${agentBadge(s.agent)}</td><td class="config-path">${s.path}</td><td><span class="chip ${s.connection==='Connected'?'success':'attention'}">${s.connection}</span></td><td><button class="btn" data-session="${index}">${s.action}</button></td></tr>`).join('');document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>{selectedSession=Number(b.dataset.session);renderDetail()});renderDetail()}
function renderDetail(){const s=examples[selectedSession];$('connection-heading').textContent=s.title;$('connection-copy').textContent=s.id+' · '+agentData[s.agent].name;
if(s.kind==='managed')$('connection-content').innerHTML=`<div class="notice"><strong>Connected · managed by Relai</strong>New prompts use this native session. The browser can close without stopping the local runtime.</div><div class="actions"><a class="btn primary" href="01-session-workspace.html">Open session</a><button class="btn" id="pause-session">Interrupt current turn</button></div>`;
if(s.kind==='saved')$('connection-content').innerHTML='<div class="notice"><strong>History found · live activity unconfirmed</strong>Resume uses the same native session ID. It does not attach to a running terminal.</div><div class="actions"><button class="btn primary" id="resume-session">Resume in Relai</button><button class="btn" id="view-history">View saved history</button></div>';
if(s.kind==='server')$('connection-content').innerHTML='<div class="notice"><strong>Connect to the existing OpenCode server</strong>Use the server already owning this session instead of starting a second one.</div><label for="endpoint">Local server address</label><div class="actions" style="margin-top:9px"><input class="field" id="endpoint" value="http://127.0.0.1:4096" aria-describedby="endpoint-help"><button class="btn primary" id="connect-server">Check & connect</button></div><p id="endpoint-help" class="muted small">Example local endpoint. Authentication stays with the local service; no password is shown here.</p>';
if(s.kind==='external')$('connection-content').innerHTML='<div class="notice attention"><strong>A saved session is not proof of a stopped terminal.</strong>This session may be active elsewhere. Relai has no confirmed control channel.</div><p>Check the native agent first. Do not automatically launch another process for the same session.</p><div class="actions"><button class="btn" id="check-external">Check again</button><button class="btn" id="native-help">How to connect</button></div>';
if($('pause-session'))$('pause-session').onclick=()=>modal('Interrupt the current turn?','<p>Interrupting a turn is separate from stopping the local service or deleting the native session.</p>',{label:'Preview interrupt',run:()=>toast('Preview only · no process interrupted')});
if($('resume-session'))$('resume-session').onclick=()=>modal('Resume saved session','<p>Keep native ID '+s.id+' and inherit the agent configuration.</p><div class="notice">Before a real resume, confirm the session has no other active owner.</div>',{label:'Preview resume',run:()=>{s.kind='managed';s.connection='Connected';s.action='Open session';render();toast('Preview only · saved session resumed')}});
if($('view-history'))$('view-history').onclick=()=>modal('Saved history','<p><strong>You:</strong> Review the workspace architecture.</p><p><strong>Claude Code:</strong> Separate the session runtime from the browser interface.</p><p class="muted small">Saved example messages. No live activity is inferred from them.</p>');
if($('connect-server'))$('connect-server').onclick=()=>{const value=$('endpoint').value;try{const url=new URL(value);if(!['http:','https:'].includes(url.protocol)||!['127.0.0.1','localhost','[::1]'].includes(url.hostname))throw Error();s.kind='managed';s.connection='Connected';s.action='Open session';render();toast('Simulated connection · no network request made')}catch{toast('Enter a valid local HTTP server address');$('endpoint').focus()}};
if($('check-external'))$('check-external').onclick=()=>toast('Example result · activity still unknown; control remains unavailable');if($('native-help'))$('native-help').onclick=()=>modal('Connect a native session','<p>Discovery, resume and attachment are different operations.</p><p>Use an agent-supported server or an explicit handoff. A terminal process ID or a history file is not enough to inject a prompt safely into a running session.</p>')}
$('preview-update').onclick=()=>modal('Connection limited after an update','<div class="notice attention"><strong>Prompt delivery unavailable</strong>The required native operation is no longer supported by this example connector.</div><p>Keep history and drafts accessible. Disable only the affected connector and show a precise recovery action.</p><a href="02-agent-profiles.html" class="btn">Review agent compatibility</a>');$('compose-example').onclick=()=>modal('Choose a session','<p>The composer can reuse this connection picker. Sessions without confirmed control show a Connect or Resume action before Send prompt becomes available.</p>');render();
'''
(out/'03-session-connections.html').write_text(shell('Session connections',connections,connectionsjs))
hub='''<main class="hub"><span class="chip">Terminal integration · design explorations</span><h1 style="margin-top:24px">One calm interface.<br>Each agent keeps its own engine.</h1><p>Three interactive sketches for Relai. Explore both themes, switch agents and try the connection states. Nothing is executed on your computer.</p><div class="grid3"><article class="card"><div class="concept-number">01 / SESSION WORKSPACE</div><h2>A session panel beside the conversation</h2><p>Keep the conversation clean. Open the session context, activity or terminal output only when needed.</p><p class="small">Try Codex, a saved Claude session and a connected OpenCode server.</p><a class="btn primary" href="01-session-workspace.html">Explore the workspace [icon:arrow-up-right]</a></article><article class="card"><div class="concept-number">02 / AGENT PROFILES</div><h2>Native configuration, inherited by default</h2><p>Personal settings, project rules, skills and optional overrides without rebuilding every agent’s settings screen.</p><p class="small">Try the skills view and simulate an agent update.</p><a class="btn primary" href="02-agent-profiles.html">Explore agent profiles [icon:arrow-up-right]</a></article><article class="card"><div class="concept-number">03 / CONNECTION STATES</div><h2>Connected, saved or still unknown</h2><p>A useful next action for each session. Resume history, connect a server, or inspect an uncertain external session.</p><p class="small">Try the recovery actions without starting a real process.</p><a class="btn primary" href="03-session-connections.html">Explore session connections [icon:arrow-up-right]</a></article></div><section class="diagram"><h2>Behind the interface</h2><p class="muted">A local service owns the connection. Agent-specific details stay in small connectors.</p><div class="flow"><div class="flow-block">Relai<small>Prompts · sessions · drafts</small></div>[icon:chevron-right]<div class="flow-block">Local service<small>Lifecycle · queue · permissions</small></div>[icon:chevron-right]<div class="flow-block">Agent connectors<small>Codex · Claude Code · OpenCode</small></div>[icon:chevron-right]<div class="flow-block">Native agent<small>Configuration · skills · execution</small></div></div></section><p class="about">Research and decisions: TERMINAL-INTEGRATION.md and UX-DECISIONS.md accompany these files. The existing Relai prototype remains separate.</p></main>'''
(out/'index.html').write_text(shell('Terminal integration concepts',hub,''))
print('Built four self-contained terminal concept HTML files.')
